// Helper function for heapify
std::function<void(int[], int, int)> heapify = [&](int arr[], int heapSize, int i) {
    int largest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;

    if (left < heapSize && arr[left] > arr[largest])
        largest = left;

    if (right < heapSize && arr[right] > arr[largest])
        largest = right;

    if (largest != i) {
        std::swap(arr[i], arr[largest]);
        heapify(arr, heapSize, largest);
    }
};

// Build max heap from the array
// Start from the last non-leaf node and heapify each node going up to root
for (int i = size / 2 - 1; i >= 0; i--) {
    heapify(arr, size, i);
}

